#!/usr/bin/env bash
# cspell:words dartaotruntime dill pubspec wonderous localsend
#
# run_producer_demand.sh -- D-PRODUCER-DEMAND-1. Second stage over the EXACT
# D-DEMAND-1 corpus: same windows, same pairs, same changed methods, same
# weighting. Nothing about the corpus is re-selected here.
#
# For each pair it builds the RELEASE side's real evidence and replays the
# shipping producer:
#
#   * the release's non-AOT import kernel (`--private-dill`), which is what
#     makes private enumeration come from pre-tree-shaking code;
#   * the release's own capability manifest, generated by the shipping
#     `route_b_gen_dynamic_interface` under policy p2 with production's
#     `--sdk-members` budget.
#
# Capabilities are NEVER derived from the candidate's source. The whole point is
# to ask what the RELEASE actually granted.
#
# NOT SUPPLIED, and it is a scope limit rather than an oversight: release
# binding/signature evidence and the survival oracle. Those describe a PUBLISHED
# release artifact, and a historical commit has none -- there is no container to
# bind to and no compiled release to ask about site survival. `produce` documents
# null for both as the host-harness path. Refusals those gates would raise are
# therefore NOT measured here, so the producer-level number this stage reports is
# itself an upper bound on the fully-gated one.
set -uo pipefail

SRC=${SRC:-/Volumes/build/route-b/flutter/engine/src}
OUT=${OUT:-$SRC/out/host_release_arm64}
DART=$OUT/dart-sdk/bin/dart
GEN_KERNEL=$SRC/flutter/third_party/dart/pkg/vm/bin/gen_kernel.dart
PLATFORM=$OUT/flutter_patched_sdk/platform_strong.dill
AOT=$OUT/dartaotruntime
GENIFACE=${GENIFACE:-$OUT/zip_archives/route_b_gen_dynamic_interface.aot}
SDK_MEMBERS='dart:core#print,dart:core#DateTime.now,dart:core#DateTime.get:millisecondsSinceEpoch,dart:core#identical'

WORK=${WORK:?WORK=<D-DEMAND-1 work dir>}
ENTRY=${ENTRY:?ENTRY=<package uri>}
APPSUB=${APPSUB:-.}
PKGARG=${PKGARG:-.dart_tool/package_config.json}
PKGREL=${PKGREL:-.dart_tool/package_config.json}
INCLUDE=${INCLUDE:?INCLUDE=<package:app/ prefix for the interface generator>}
CLI=${CLI:-/Users/mendell/shorebird/packages/shorebird_cli}

die() { echo "ERROR: $*" >&2; exit 1; }
[ -d "$WORK/pairs" ] || die "no D-DEMAND-1 pairs under $WORK"
[ -f "$GENIFACE" ] || die "no interface generator at $GENIFACE"
mkdir -p "$WORK/import" "$WORK/manifest" "$WORK/producer"

WT=$WORK/wt
[ -d "$WT" ] || die "no worktree at $WT"

for pair in "$WORK"/pairs/*.json; do
  name=$(basename "$pair" .json)
  bp=${name%%_*}
  base=$(grep "^$bp" "$WORK/window.txt" | head -1)
  [ -n "$base" ] || { echo "  $name: base not in window"; continue; }
  group=$(awk -v s="$base" '$1==s{print $2}' "$WORK/lockgroups.txt")

  # Inert pairs have nothing to replay. Building a release's import kernel and
  # manifest for a pair with no changed method costs a minute and answers
  # nothing, so they are skipped -- this changes no observation, since a pair
  # with no changed method contributes none.
  if ! python3 -c "import json,sys; sys.exit(0 if json.load(open('$pair')).get('changed') else 1)"; then
    continue
  fi

  imp=$WORK/import/$base.import.dill
  man=$WORK/manifest/$base.manifest.json

  if [ ! -f "$man" ]; then
    git -C "$WT" checkout --quiet --force --detach "$base" 2>/dev/null || {
      echo "  $name: checkout failed"; continue; }
    mkdir -p "$WT/$(dirname "$PKGREL")"
    cp "$WORK/pkgcfg/$group/package_config.json" "$WT/$PKGREL" 2>/dev/null || {
      echo "  $name: no resolution for group $group"; continue; }

    if [ ! -f "$imp" ]; then
      # NON-AOT and NOT platform-linked: private enumeration must see members
      # TFA would have shaken out, and field lowering must not have happened.
      ( cd "$WT/$APPSUB" && timeout 1800 "$DART" "$GEN_KERNEL" \
          --platform "$PLATFORM" --target flutter --no-aot --no-link-platform \
          --packages "$PKGARG" -o "$imp" "$ENTRY" ) \
          > "$WORK/import/$base.log" 2>&1
    fi
    [ -f "$imp" ] || { echo "  ${base:0:8}: import kernel FAILED"; continue; }

    timeout 1800 "$AOT" "$GENIFACE" \
      --dill "$WORK/dills/$base.dill" \
      --out "$WORK/manifest/$base.interface.yaml" \
      --include "$INCLUDE" \
      --private-dill "$imp" \
      --policy p2 \
      --manifest "$man" \
      --sdk-members "$SDK_MEMBERS" \
      > "$WORK/manifest/$base.gen.log" 2>&1
    [ -f "$man" ] || { echo "  ${base:0:8}: manifest FAILED"; continue; }
    echo "  ${base:0:8}: release evidence built"
  fi

  # THE WORKTREE MUST BE AT THE CANDIDATE FOR THE REPLAY.
  #
  # The producer reads the body's source from `span.fileUri`, which points into
  # this worktree. Building the release's manifest above left the tree at the
  # BASE commit, so replaying there reads the RELEASE's text against the
  # CANDIDATE's spans -- which produced refusals like "its recorded source span
  # runs past the end of <file>" and "its parameter list could not be found"
  # that describe the harness, not the change.
  cand=$(grep "^${name##*_}" "$WORK/window.txt" | head -1)
  cgroup=$(awk -v s="$cand" '$1==s{print $2}' "$WORK/lockgroups.txt")
  git -C "$WT" checkout --quiet --force --detach "$cand" 2>/dev/null || {
    echo "  $name: candidate checkout failed"; continue; }
  mkdir -p "$WT/$(dirname "$PKGREL")"
  cp "$WORK/pkgcfg/$cgroup/package_config.json" "$WT/$PKGREL" 2>/dev/null || true

  ( cd "$CLI" && timeout 1800 dart run tool/demand_replay_refusal.dart \
      "$pair" --enumerate --manifest "$man" --release-import "$imp" ) \
      > "$WORK/producer/$name.txt" 2>&1
  n=$(grep -c '^  REFUSE' "$WORK/producer/$name.txt" 2>/dev/null || echo 0)
  echo "  $name: producer refusals = $n"
done
echo "==> producer replays in $WORK/producer"
